#!/usr/bin/env bash
# Burned-in subtitles (.srt) + an animated lower-third name card, ffmpeg only.
# The "clip" is generated by ffmpeg too (animated gradients source), so the
# demo needs no footage. Swap it for `-i your_clip.mp4` in real use.
#
# Run:  bash subtitles.sh          -> out/ffmpeg-subtitles.mp4
set -e
cd "$(dirname "$0")"
mkdir -p out

DUR=10
# drawtext needs a font file; on Windows the drive colon must be escaped (C\:)
BOLD="C\\:/Windows/Fonts/segoeuib.ttf"
REG="C\\:/Windows/Fonts/segoeui.ttf"

# Name card timing: slides in at 1.0 s, slides out at 7.5 s.
# The first min() goes 0 -> 1 over 0.4 s, the second 1 -> 0; their product
# (0..1) drives the card's x position. (\, escapes commas inside a filter.)
SHOW="min(1\,max(0\,(t-1)/0.4))*min(1\,max(0\,(7.9-t)/0.4))"

# Input 0: the background "clip".  Input 1: a 420x100 card we draw text on.
# The card is built once, then overlay= slides it in (eval=frame re-evaluates x each frame).
ffmpeg -y -v error \
  -f lavfi -i "gradients=s=1280x720:r=30:d=$DUR:n=3:c0=0x0f1b33:c1=0x2f5aa8:c2=0x0a1222:speed=0.03:seed=4" \
  -f lavfi -i "color=c=0xf5f7fb@0.95:s=420x100:r=30:d=$DUR,format=rgba" \
  -filter_complex "
    [1]drawbox=x=0:y=0:w=8:h=100:color=0xffb547:t=fill,
       drawtext=fontfile='$BOLD':text='Alex Morgan':fontsize=36:fontcolor=0x0f1b33:x=28:y=12,
       drawtext=fontfile='$REG':text='Host  |  ffmpeg filters demo':fontsize=22:fontcolor=0x5a6a85:x=28:y=60[card];
    [0][card]overlay=x='-440+480*$SHOW':y=460:eval=frame,
       subtitles=subs.srt:force_style='FontName=Segoe UI,FontSize=22,PrimaryColour=&H00FFFFFF,BorderStyle=3,OutlineColour=&H80000000,Outline=6,Shadow=0,MarginV=28',
       fade=t=in:d=0.4,fade=t=out:st=$((DUR - 1)):d=1,format=yuv420p[v]" \
  -map "[v]" -c:v libx264 -preset slow -crf 23 -movflags +faststart \
  out/ffmpeg-subtitles.mp4

echo "done: out/ffmpeg-subtitles.mp4"
